package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.medical.persistence.VerificationInputFixture.*;
class ModelVerificationInputServiceTest {
 VerificationInputFixture f;
 @BeforeEach void before()throws Exception{f=new VerificationInputFixture();}
 @AfterEach void after()throws Exception{f.close();}
 @Test void realSourceSelectionSnapshotAndGetProduceActual076Input()throws Exception{
  var receipt=f.register();assertEquals(PROJECT,receipt.path("project_id").asText());assertEquals("EXACT_INPUT",receipt.path("artifact_kind").asText());
  String artifact=receipt.at("/exact_input/artifact_id").asText();var row=f.registrations.get(artifact);assertNotNull(row);assertEquals(f.original.reference(),f.artifactRows.get(artifact).reference());assertEquals("SOURCE",f.bindings.get(artifact).resourceKind());
  assertEquals(f.snapshots.get(row.snapshotId()).manifestHash(),receipt.at("/scope_snapshot_basis/content_sha256").asText());assertEquals(1,f.snapshotMembers.get(row.snapshotId()).size());assertTrue(receipt.at("/exact_input/coverage/complete").asBoolean());
  assertEquals(receipt,f.service.read(f.subject,"1",artifact).path("receipt"));assertTrue(f.requests.get()>0);assertTrue(f.states.get()>f.requests.get());assertEquals(1,f.snapshots.size());
 }
 @Test void originalKeyDoesNotCreateSecondSnapshotAcrossNewSession()throws Exception{var receipt=f.register();int writes=f.writes.size();when(f.subject.sessionId()).thenReturn(id(77));assertEquals(receipt,f.register());assertEquals(writes,f.writes.size());assertEquals(1,f.snapshots.size());}
 @Test void recoveryReturnsExactOriginalRequestAndOriginalKey()throws Exception{var receipt=f.register();var recovery=f.service.recover(f.subject,"1",receipt.path("operation_id").asText());assertEquals(KEY,recovery.path("original_idempotency_key").asText());assertEquals(f.request(),recovery.path("original_request"));assertEquals(receipt,recovery.path("receipt"));}
 @Test void modelVerifyIsRequiredBeforeAnyOriginalGet(){f.grants.removeIf(g->g.action().equals("model.verify"));assertThrows(Exception.class,f::register);assertEquals(0,f.requests.get());assertTrue(f.writes.isEmpty());}
 @Test void artifactRegisterIsIndependentOfModelVerify(){f.grants.removeIf(g->g.action().equals("artifact.register"));assertThrows(Exception.class,f::register);assertEquals(0,f.requests.get());}
 @Test void sourceReadIsIndependentOfModelVerify(){f.grants.removeIf(g->g.action().equals("source.read"));assertThrows(Exception.class,f::register);assertEquals(0,f.requests.get());}
 @Test void taskCreateIsNotNeededAndNoAgentOrTaskIsInvented()throws Exception{assertFalse(f.grants.stream().anyMatch(g->g.action().equals("task.create")));f.register();assertEquals(1,f.snapshots.size());assertFalse(f.writes.stream().anyMatch(s->s.toLowerCase().contains("task")||s.toLowerCase().contains("agent")));}
 @Test void providerSendPermissionIsNotSynthesizedByPreparation()throws Exception{f.register();assertFalse(f.grants.stream().anyMatch(g->g.action().equals("model.send")||g.action().equals("source.external.process")));}
 @Test void purposeCannotBeConvertedToSimulationOrEvaluation(){for(String purpose:List.of("SIMULATION_EVALUATION","EVALUATION_RESULTS","MODEL_CONFIGURATION")){var request=f.request().put("business_purpose",purpose);assertThrows(Exception.class,()->f.service.register(f.subject,"1",KEY,request));}assertEquals(0,f.requests.get());}
 @Test void missingSourceSelectionCannotInventIndexedCandidate(){when(f.sources.scopeCandidates(anyString(),eq(PROJECT),anyString(),anyList(),anyList(),anyInt())).thenReturn(List.of());assertThrows(Exception.class,f::register);assertEquals(0,f.requests.get());}
 @Test void missingCurrentParseOrApprovalRejectsBeforeGet(){when(f.sources.snapshotCandidate(anyString(),eq(PROJECT),anyString(),anyString(),anyString(),anyString(),anyString())).thenReturn(List.of());assertThrows(Exception.class,f::register);assertEquals(0,f.requests.get());}
 @Test void bytesChangedAtActualGetCannotCreateRegistration(){f.corrupt.set(true);assertThrows(Exception.class,f::register);assertTrue(f.registrations.isEmpty());assertTrue(f.snapshots.isEmpty());}
 @Test void revocationDuringGetRejectsBeforeSnapshot(){f.onGet=()->f.allowed.set(false);assertThrows(Exception.class,f::register);assertTrue(f.snapshots.isEmpty());}
 @Test void formalEvaluationDocumentIsNotAnExactInput()throws Exception{var doc=f.json.object().put("schema_version","1.0.0").put("document_type","PTR").put("language","en");doc.putArray("sections");f.bytes(f.wire.canonical(doc).getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThrows(Exception.class,f::register);assertTrue(f.snapshots.isEmpty());}
 @Test void originalSnapshotCannotBeSubstitutedDuringRead()throws Exception{var receipt=f.register();f.snapshots.clear();assertThrows(Exception.class,()->f.service.read(f.subject,"1",receipt.at("/exact_input/artifact_id").asText()));}
 @Test void missingAuditCannotBeRecovered()throws Exception{var receipt=f.register();f.audits.clear();assertThrows(Exception.class,()->f.service.recover(f.subject,"1",receipt.path("operation_id").asText()));}
 @Test void outboxChangeCannotBeRecovered()throws Exception{var receipt=f.register();f.events.replaceAll((k,v)->"{}");assertThrows(Exception.class,()->f.service.recover(f.subject,"1",receipt.path("operation_id").asText()));}
 @Test void sourceMetadataCandidateDoesNotClaimValidatedBytes()throws Exception{assertEquals("NOT_READ",f.wire.validate("Candidates",candidate()).at("/sources/0/content_validation").asText());}
 @Test void actualCandidateReadHasNoGetWriteOrSnapshotSideEffects()throws Exception{var result=f.candidates.read(f.subject,"1",MODEL,PURPOSE);assertEquals(PROFILE,result.at("/profile_basis/version_id").asText());assertEquals(SOURCE,result.at("/sources/0/source/version_id").asText());assertEquals("NOT_READ",result.at("/sources/0/content_validation").asText());assertEquals(0,f.requests.get());assertTrue(f.writes.isEmpty());assertTrue(f.snapshots.isEmpty());}
 @Test void actualEmptyCandidatesExplainMissingInput()throws Exception{when(f.sources.scopeCandidates(anyString(),eq(PROJECT),anyString(),anyList(),anyList(),anyInt())).thenReturn(List.of());var result=f.candidates.read(f.subject,"1",MODEL,PURPOSE);assertTrue(result.path("sources").isEmpty());assertEquals("NO_CURRENT_PROJECT_SOURCE_CANDIDATE",result.path("missing_input_reasons").get(0).asText());assertTrue(f.writes.isEmpty());}
 @Test void candidateReadRequiresModelVerify(){f.grants.removeIf(g->g.action().equals("model.verify"));assertThrows(Exception.class,()->f.candidates.read(f.subject,"1",MODEL,PURPOSE));assertEquals(0,f.requests.get());}
 @Test void candidateDoesNotPretendRegisterPermissionExists(){f.grants.removeIf(g->g.action().equals("artifact.register"));assertTrue(f.candidates.read(f.subject,"1",MODEL,PURPOSE).path("sources").isEmpty());assertTrue(f.writes.isEmpty());}
 @Test void sourceFromAnotherProjectCannotBeRegistered(){var s=f.sourceRows.get(SOURCE);f.sourceRows.put(SOURCE,new SourceReadProtocol.SourceRow(s.tenantId(),s.sourceId(),s.sourceVersion(),id(800),"PROJECT",s.classification(),s.rightsRevision(),s.originalSha256(),s.registeredSha256(),id(800)));assertThrows(Exception.class,f::register);assertEquals(0,f.requests.get());}
 @Test void evaluationEntryUsesSameRealPersistenceCoreWithoutTaskGrant()throws Exception{var scope=new CommonProtocol.SourceScope(CommonProtocol.ScopeMode.SOURCE_VERSIONS,List.of(),List.of(SOURCE),false,null,null);f.transaction(()->{var result=f.snapshotStore.saveForEvaluation(f.admission,PROJECT,PROFILE,scope,id(7),PURPOSE,"OFFLINE_TEST","LOCAL",ModelVerificationInputService.LIMITS);assertEquals(1,result.manifest().members().size());assertEquals(result,f.snapshotStore.readForEvaluation(f.admission,PROJECT,PROFILE,scope,id(7),PURPOSE,"OFFLINE_TEST","LOCAL",ModelVerificationInputService.LIMITS,new PermissionProtocol.Basis(result.snapshot().snapshotId(),result.snapshot().manifestHash())));return null;});assertEquals(1,f.snapshots.size());}
 @Test void evaluationEntryCannotBorrowModelVerifyGrant(){f.grants.removeIf(g->g.action().equals("evaluation.run"));assertThrows(Exception.class,()->f.transaction(()->f.snapshotStore.saveForEvaluation(f.admission,PROJECT,PROFILE,new CommonProtocol.SourceScope(CommonProtocol.ScopeMode.SOURCE_VERSIONS,List.of(),List.of(SOURCE),false,null,null),id(7),PURPOSE,"OFFLINE_TEST","LOCAL",ModelVerificationInputService.LIMITS)));assertTrue(f.snapshots.isEmpty());}
 @Test void extraSnapshotParentFailsBeforeOriginalRead()throws Exception{var receipt=f.register();f.snapshotParents.values().iterator().next().add(id(900));int reads=f.requests.get();assertThrows(Exception.class,()->f.service.read(f.subject,"1",receipt.at("/exact_input/artifact_id").asText()));assertEquals(reads,f.requests.get());}
 ObjectNode candidate(){var r=f.json.object().put("schema_version","1.0.0").put("project_id",PROJECT).put("model_config_revision",MODEL).put("business_purpose",PURPOSE);r.set("profile_basis",f.json.tree(new PermissionProtocol.Basis(PROFILE,hash("profile"))));var s=r.putArray("sources").addObject().put("source_id",SOURCE_ID).put("rights_revision",RIGHTS).put("size_bytes","100").put("media_type","application/json").put("content_validation","NOT_READ");s.set("source",f.json.tree(new PermissionProtocol.Basis(SOURCE,f.original.sha256())));r.putArray("missing_input_reasons").add("EXACT_INPUT_CONTENT_VALIDATION_REQUIRED");return r;}
}
